def build_controller():
    return {
        "name": "det_tsp_hh_oracle_portfolio_v3",
        "description": "Deterministic instance-adaptive scheduler over frozen TSP heuristic portfolio with stagnation-triggered switching and bounded schedule tuning.",
        "default_heuristic": "farthest_insertion_two_opt",
        "random_like_heuristic": "nearest_neighbor_multistart",
        "clustered_heuristic": "cluster_first_local_search",
        "grid_like_heuristic": "candidate_pruned_two_opt",
        "two_cluster_bottleneck_heuristic": "edge_preserving_restart",
        "corridor_heuristic": "limited_three_opt",
        "nearest_neighbor_trap_heuristic": "annealed_multi_start",
        "stagnation_switch_heuristic": "nearest_neighbor_multistart",
        "stagnation_threshold": 4,
        "low_improvement_threshold": 0.12,
        "failed_perturbation_threshold": 3,
        "time_budget_trigger": 0.7,
        "candidate_limit_offset": 1,
        "restart_offset": 2,
        "temperature_scale": 1.25,
        "acceptance_bias": 0.008,
        "policy": {
            "deterministic_selection_order": [
                "nearest_neighbor_trap",
                "two_cluster_bottleneck",
                "corridor",
                "grid_like",
                "clustered",
                "default",
            ],
            "tests": {
                "nearest_neighbor_trap": {
                    "use_if": "nearest-neighbor-trap-score >= 0.25 OR nn_distance_cv >= 0.62",
                    "heuristic": "nearest_neighbor_trap_heuristic",
                },
                "two_cluster_bottleneck": {
                    "use_if": "bottleneck-score >= 0.50 OR structure_class == 'two_cluster_bottleneck'",
                    "heuristic": "two_cluster_bottleneck_heuristic",
                },
                "corridor": {
                    "use_if": "corridor_score >= 0.44 AND grid_likeness <= 0.18",
                    "heuristic": "corridor_heuristic",
                },
                "grid_like": {
                    "use_if": "grid_likeness >= 0.28 OR convex_hull_ratio <= 0.82",
                    "heuristic": "grid_like_heuristic",
                },
                "clustered": {
                    "use_if": "clustering-score >= 0.42 OR structure_class == 'clustered'",
                    "heuristic": "clustered_heuristic",
                },
            },
            "online_schedule_rules": {
                "stagnation_switch": {
                    "trigger_if": "stagnation_length >= stagnation_threshold OR (recent_improvement_rate < low_improvement_threshold AND accepted_swaps == 0)",
                    "switch_to": "stagnation_switch_heuristic",
                    "offsets": {
                        "candidate_limit_offset": "candidate_limit_offset if grid_likeness >= 0.25 else 0",
                        "restart_offset": "restart_offset if time_budget_used >= 0.35 else 1",
                    },
                },
                "perturbation_escalation": {
                    "trigger_if": "failed_perturbation_count >= failed_perturbation_threshold AND time_budget_used >= time_budget_trigger",
                    "escalate_to": {
                        "if_current_heuristic_contains": "two_opt",
                        "then": "two_cluster_bottleneck_heuristic",
                        "else": "nearest_neighbor_trap_heuristic",
                    },
                    "temperature_tuning": {
                        "temperature_scale": "temperature_scale",
                        "acceptance_bias": "acceptance_bias",
                    },
                },
                "late_stage_refinement_preference": {
                    "trigger_if": "time_budget_used >= (time_budget_trigger + 0.18)",
                    "policy": "only allow stagnation_switch; avoid additional portfolio cycling; keep current heuristic otherwise.",
                },
            },
            "restart_budgeting": {
                "max_restarts": "1 + (restart_offset if stagnation_length >= 2 else 0)",
                "candidate_list_bias": "candidate_limit_offset if grid_likeness >= 0.25 else 0",
            },
            "tie_breaking": {
                "prefer_more_specialized": True,
                "prefer_longer_horizon_when_time_rich": "if time_budget_used < time_budget_trigger then prefer multi-start styles: nearest_neighbor_multistart/annealed_multi_start else prefer cheaper/simpler: farthest_insertion_two_opt/candidate_pruned_two_opt",
            },
        },
        "portfolio": {
            "heuristics": [
                "nearest_neighbor_trap_heuristic",
                "two_cluster_bottleneck_heuristic",
                "corridor_heuristic",
                "grid_like_heuristic",
                "clustered_heuristic",
                "random_like_heuristic",
                "default_heuristic",
            ],
            "tuning_bounds": {
                "max_candidate_limit_multiplier": 3,
                "temperature_multiplier_bounds": [0.6, 1.8],
                "restart_multiplier_bounds": [0, 3],
            },
        },
        "determinism": {
            "seed_policy": "derive_from_instance_hash",
            "schedule_policy": "fully_deterministic",
            "tie_breaker": "lexicographic_by_portfolio_order_then_fixed_param_order",
        },
    }

